import numpy as np

class FractalBasin:
    def __init__(self, dim=5):
        self.dim = dim
        # Base frequencies for each dimension
        self.base_freqs = np.linspace(1.0, 3.0, dim)
        # Recursion depth for fractal pattern
        self.depth = 3

    def _recursive_harmonic(self, x, freq, depth):
        if depth == 0:
            return np.sum(np.sin(freq * x) ** 2)

        r = np.linalg.norm(x)
        current = np.sum(np.sin(freq * x) ** 2) * (1 + 0.5 * np.cos(2 * np.pi * r / 5.0))
        next_freq = freq * 1.5
        return current + 0.3 * self._recursive_harmonic(x, next_freq, depth - 1)

    def f(self, x):
        # Base quadratic bowl
        base = np.sum(x**2)

        # Fractal harmonic component
        fractal = self._recursive_harmonic(x, self.base_freqs[0], self.depth)

        # Dimension-wise coupling
        coupling = 0.1 * np.sum(np.abs(x) ** (3/2))

        return base + 5 * fractal + coupling
